SELECT ds.shift_id, ds.employee_id, ds.clinic_id, ds.work_date, ds.start_time, ds.end_time, e.full_name AS dentist_name, d.title, d.specialty, c.clinic_name, c.clinic_code, (SELECT string_agg(dq.qualification_id::text, ',') FROM dentist_qualification dq WHERE dq.employee_id = ds.employee_id) AS qual_csv FROM dentist_schedule ds JOIN dentist d ON d.employee_id = ds.employee_id JOIN employee e ON e.employee_id = ds.employee_id JOIN clinic c ON c.clinic_id = ds.clinic_id WHERE ds.work_date = #{date} AND e.status = '在职' AND c.status = '营业'
AND ds.clinic_id = #{clinicId}
ORDER BY ds.start_time, ds.employee_id

SELECT ds.shift_id, ds.employee_id, ds.clinic_id, ds.work_date, ds.start_time, ds.end_time,
       e.full_name AS dentist_name, d.title, d.specialty,
       c.clinic_name, c.clinic_code
FROM dentist_schedule ds
JOIN dentist  d ON d.employee_id = ds.employee_id
JOIN employee e ON e.employee_id = ds.employee_id
JOIN clinic   c ON c.clinic_id   = ds.clinic_id
WHERE ds.employee_id = #{employeeId}
  AND ds.work_date   = #{date}
  AND ds.clinic_id   = #{clinicId}
  AND ds.start_time <= #{startTime}
  AND ds.end_time   >= #{endTime}
LIMIT 1

SELECT employee_id, appointment_time AS start_at, appointment_time + (expected_minutes * INTERVAL '1 minute') AS end_at FROM appointment WHERE status <> '已取消' AND employee_id IN
#{id}
AND tsrange(appointment_time, appointment_time + (expected_minutes * INTERVAL '1 minute'), '[)') && tsrange(#{dayStart}, #{dayEnd}, '[)') ORDER BY employee_id, appointment_time

SELECT 
FROM appointment a
JOIN patient  p ON p.patient_id  = a.patient_id
JOIN employee e ON e.employee_id = a.employee_id
JOIN clinic   c ON c.clinic_id   = a.clinic_id
WHERE a.appointment_time >= #{dayStart}
  AND a.appointment_time <  #{dayEnd}

  AND a.clinic_id = #{clinicId}


  AND a.employee_id = #{employeeId}


  AND a.status = #{status}

ORDER BY a.appointment_time

SELECT FROM appointment a JOIN patient p ON p.patient_id = a.patient_id JOIN employee e ON e.employee_id = a.employee_id JOIN clinic c ON c.clinic_id = a.clinic_id WHERE a.status = '待就诊' AND a.appointment_time + (a.expected_minutes * INTERVAL '1 minute') + make_interval(mins => #{graceMinutes}) < #{now}
AND a.clinic_id = #{clinicId}
ORDER BY a.appointment_time

SELECT COUNT(*) FROM appointment
WHERE patient_id = #{patientId}
  AND status = '未到诊'
  AND appointment_time >= #{since}

